using Microsoft.AspNetCore.Mvc;

namespace Web.Controllers;

[Route("dashboard")]
public class DashboardController : Controller
{
    [HttpGet("")]
    public IActionResult Index()
    {
        return View();
    }
}

.dashboard-container {
    display: flex;
}

.dashboard-aside {
    width: 250px;
    background-color: var(--mt-surface-deep);
    padding: 1rem;
    border-right: 1px solid var(--mt-border-strong);
}

.dashboard-nav-list {
    list-style: none;
    padding: 0;
    margin: 0;
}

.dashboard-nav-link {
    display: block;
    padding: 0.75rem 1rem;
    color: var(--mt-text-muted);
    text-decoration: none;
    border-radius: var(--radius);
    transition: var(--transition);
    font-family: var(--font-body);
    font-weight: 600;
}

.dashboard-nav-link:hover {
    background-color: var(--mt-surface-hover);
    color: var(--mt-text);
}

.dashboard-nav-link.active {
    background-color: var(--mt-highlight);
    color: var(--mt-text-on-light);
    font-weight: 700;
}

.dashboard-layout {
    display: flex;
    min-height: calc(100vh - 78px); /* Adjust 78px based on header height */
}

.dashboard-aside {
    width: 240px;
    flex-shrink: 0;
    background-color: var(--mt-surface-deep); 
    border-right: 1px solid var(--mt-border-strong);
    padding: 1.5rem 0;
}

.dashboard-nav-list {
    list-style: none;
    padding: 0;
    margin: 0;
}

.dashboard-nav-item {
    margin-bottom: 0.5rem;
}

.dashboard-nav-link {
    display: flex;
    align-items: center;
    padding: 0.8rem 1.5rem;
    color: var(--mt-text-muted);
    text-decoration: none;
    font-family: "Roboto", sans-serif;
    font-weight: 500;
    font-size: 0.95rem;
    border-left: 3px solid transparent;
    transition: all 0.3s ease;
}

.dashboard-nav-link:hover {
    color: var(--mt-text);
    background-color: var(--mt-surface-hover);
}

.dashboard-nav-link.active {
    color: var(--mt-text-on-tint);
    background-color: var(--mt-highlight-soft);
    border-left-color: var(--mt-highlight);
    font-weight: 600;
}

.dashboard-nav-link .fa-solid {
    width: 20px;
    margin-right: 12px;
    text-align: center;
}

.dashboard-main-content {
    flex-grow: 1;
    padding: 2rem;
}

