namespace Data.Dto.CRUD.ScheduledMatch;

public class ScheduledMatchListDto
{
    public Guid Id { get; set; }
    public Guid PlayingFieldId { get; set; }
    public string PlayingFieldName { get; set; } = string.Empty;
    public Guid PartyId { get; set; }
    public string PartyDescription { get; set; } = string.Empty;
    public DateTime MatchDate { get; set; }
}

using Data.Dto.CRUD.ScheduledMatch;
using Microsoft.AspNetCore.Mvc.Rendering;

namespace Web.Models.Dashboard;

public class ScheduledMatchFormViewModel
{
    public ScheduledMatchFormDto Form { get; set; } = new();
    public List<SelectListItem> PlayingFields { get; set; } = new();
    public List<SelectListItem> Parties { get; set; } = new();
}

@{
    ViewData["Title"] = "Dashboard - Scheduled Matches";
}

<section class="dashboard-panel">
    <button type="button" class="dashboard-add-button" onclick="openCreate()">+ Add Scheduled Match</button>
    <header class="dashboard-panel-header">
        <h2 class="dashboard-panel-title">Scheduled Matches</h2>
    </header>
    <div style="display:flex;justify-content:center;">
        <table class="dashboard-table" aria-label="Scheduled matches table">
            <thead>
                <tr>
                    <th>Playing Field</th>
                    <th>Party</th>
                    <th>Match Date</th>
                    <th>Action</th>
                </tr>
            </thead>
            <tbody id="scheduledMatchesTable">
                <!-- Ajax: inject scheduled match rows here -->
            </tbody>
        </table>
    </div>
</section>

<div id="form-container"></div>

@section Scripts {
    <script>
        const tableBody = document.getElementById("scheduledMatchesTable");
        document.addEventListener("DOMContentLoaded", async () => {
            await loadScheduledMatches();
        })

        tableBody.addEventListener("click", function(e) {
            if (e.target.classList.contains("dashboard-row-button-edit")) {
                const match = JSON.parse(e.target.dataset.match);
                editScheduledMatch(match);
            }
        });

        //injeted form actions
        function fetchForm(callback) {
            $.get("/scheduled-matches/form", function (html) {
                $("#form-container").html(html);
                $.validator.unobtrusive.parse("#scheduled-match-form");
                if (callback) callback();
            });
        }

        function cancelForm() {
            $("#form-container").html("");
        }

        //Read
        function loadScheduledMatches() {
            $.ajax({
                url: "/scheduled-matches/data",
                method: "GET",
                success: function (matches) {
                    let injectedHtml = "";
                    matches.forEach(match => {
                        injectedHtml +=
                        `
                        <tr>
                            <td>${match.playingFieldName}</td>
                            <td>${match.partyDescription}</td>
                            <td>${match.matchDate}</td>
                            <td>
                                <button class="dashboard-row-button dashboard-row-button--danger dashboard-row-button-edit" data-match='${JSON.stringify(match)}'>Edit</button>
                                <button class="dashboard-row-button dashboard-row-button--danger" onclick="deleteScheduledMatch('${match.id}')">Delete</button>
                            </td>
                        </tr>
                        `
                    });
                    tableBody.innerHTML = injectedHtml;
                }
            });
        }

        //Create
        function openCreate() {
            fetchForm(() => $("#scheduled-match-id").val(""));
        }

        function submitForm() {
            const id = $("#scheduled-match-id").val();
            const url = id ? `/scheduled-matches/edit/${id}` : "/scheduled-matches/create";
            const method = "POST";

            if (!$("#scheduled-match-form").valid()) return;

            $.ajax({
                url: url,
                method: method,
                contentType: "application/json",
                data: JSON.stringify({
                    id: $("#scheduled-match-id").val() || null,
                    playingFieldId: $("#Form_PlayingFieldId").val(),
                    partyId: $("#Form_PartyId").val(),
                    matchDate: $("#Form_MatchDate").val()
                }),
                success: function () {
                    cancelForm();
                    loadScheduledMatches();
                },
                error: function (xhr) {
                    console.log(xhr.responseJSON);
                }
            });
        }

        //Delete
        function deleteScheduledMatch(id) {
            if (!confirm("Are you sure?")) return;

            $.ajax({
                url: `/scheduled-matches/delete/${id}`,
                method: "DELETE",
                success: function () {
                    loadScheduledMatches();
                },
                error: function (xhr) {
                    console.log(xhr.responseJSON);
                }
            });
        }

        //Edit
        function editScheduledMatch(match){
            fetchForm(() => {
                $("#scheduled-match-id").val(match.id);
                $("#Form_PlayingFieldId").val(match.playingFieldId);
                $("#Form_PartyId").val(match.partyId);
                $("#Form_MatchDate").val(match.matchDate);
            });
        }
    </script>
}

