+                var atIndex = email.IndexOf('@');
+                var dotIndex = email.LastIndexOf('.');
+                if (atIndex <= 0 || dotIndex <= atIndex + 1 || dotIndex == email.Length - 1)
+                {
+                    errors.Add(new Error(ErrorType.Validation, "Email format is invalid."));
+                }
+            }
+
+            if (entity.Age.HasValue && (entity.Age.Value < 10 || entity.Age.Value > 100))
+            {
+                errors.Add(new Error(ErrorType.Validation, "Age must be between 10 and 100."));
+            }
+
+            if (!string.IsNullOrWhiteSpace(entity.Username))
+            {
+                var username = entity.Username.Trim().ToLowerInvariant();
+                var usernameExists = _dbContext.Players.Any(player =>
+                    player.Id != entity.Id && player.Username.ToLowerInvariant() == username);
+                if (usernameExists)
+                {
+                    errors.Add(new Error(ErrorType.Validation, "Username is already in use."));
+                }
+            }
+
+            if (!string.IsNullOrWhiteSpace(entity.Email))
+            {
+                var email = entity.Email.Trim().ToLowerInvariant();
+                var emailExists = _dbContext.Players.Any(player =>
+                    player.Id != entity.Id && player.Email.ToLowerInvariant() == email);
+                if (emailExists)
+                {
+                    errors.Add(new Error(ErrorType.Validation, "Email is already in use."));
+                }
+            }
+
+            return errors.Count == 0 ? Result.Success() : Result.Failure(errors);
+        }
+    }
 }
